h d="M2.5 12s3.3-6 9.5-6 9.5 6 9.5 6-3.3 6-9.5 6-9.5-6-9.5-6Z" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="2.7" stroke="currentColor" stroke-width="1.7"/></svg></span><span><strong>Lihat detail</strong><small>Buka informasi pengajuan</small></span></a>@can('update',$item)@if($item->status === 'needs_revision')<a class="dropdown-item" role="menuitem" href="{{ route('workspace.hris.overtime.edit',$item) }}"><span class="overtime-menu-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m14 5 5 5M4 20l4.2-.8L19 8.4 15.6 5 4.8 15.8 4 20Z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span><strong>Perbaiki pengajuan</strong><small>Tanggapi permintaan revisi</small></span></a>@elseif($item->status === 'draft')<a class="dropdown-item" role="menuitem" href="{{ route('workspace.hris.overtime.edit',$item) }}"><span class="overtime-menu-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 20h4l10.8-10.8a2.1 2.1 0 0 0-4-4L4 16v4Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg></span><span><strong>Lanjutkan draft</strong><small>Edit dan kirim pengajuan</small></span></a><form method="POST" action="{{ route('workspace.hris.overtime.destroy',$item) }}" class="dropdown-item p-0" data-confirm="Hapus draft pengajuan lembur ini? Draft tidak dapat dipulihkan.">@csrf @method('DELETE')<button class="dropdown-item text-danger" type="submit"><span class="overtime-menu-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span><strong>Hapus draft</strong><small>Draft tidak dapat dipulihkan</small></span></button></form>@endif@endcan</div></td></tr>@empty<tr><td colspan="6" class="text-center text-secondary py-5">Belum ada pengajuan lembur sesuai filter.</td></tr>@endforelse</tbod