<script>
document.addEventListener('DOMContentLoaded', () => {
    const summaryPanel = document.querySelector('#overtime-summary-mobile-panel');
    const filterForm = document.querySelector('form.workspace-list-filter-form');
    if (summaryPanel && filterForm) filterForm.before(summaryPanel);
    const dateFrom = document.querySelector('input[name="date_from"]');
    const dateTo = document.querySelector('input[name="date_to"]');
    if (dateFrom && !dateFrom.value) dateFrom.value = @json($dateFrom);
    if (dateTo && !dateTo.value) dateTo.value = @json($dateTo);
    let activeMenu = null;
    const closeMenu = (restoreFocus = false) => { if (!activeMenu) return; activeMenu.menu.classList.remove('show'); activeMenu.toggle.setAttribute('aria-expanded', 'false'); if (restoreFocus) activeMenu.toggle.focus(); activeMenu = null; };
    const placeMenu = () => { if (!activeMenu) return; const { menu, toggle } = activeMenu; const anchor = toggle.getBoundingClientRect(); menu.style.visibility = 'hidden'; menu.style.left = '0px'; menu.style.top = '0px'; const box = menu.getBoundingClientRect(); menu.style.left = `${Math.max(8, Math.min(window.innerWidth - box.width - 8, anchor.right - box.width))}px`; const below = anchor.bottom + 8; menu.style.top = `${below + box.height <= window.innerHeight - 8 ? below : Math.max(8, anchor.top - box.height - 8)}px`; menu.style.visibility = 'visible'; };
    document.addEventListener('click', (event) => { const toggle = event.target.closest('[data-overtime-index-toggle]'); if (toggle) { event.preventDefault(); if (activeMenu?.toggle === toggle) return closeMenu(); closeMenu(); const menu = document.getElementById(toggle.dataset.menuId); if (!menu) return; document.body.append(menu); menu.classList.add('show'); toggle.setAttribute('aria-expanded', 'true'); activeMenu = { menu, toggle }; placeMenu(); return; } if (activeMenu?.menu.contains(event.target)) { if (event.target.closest('a')) closeMenu(); return; } closeMenu(); });
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeMenu(true); });
    window.addEventListener('resize', placeMenu);
    window.addEventListener('scroll', placeMenu, true);
});
</script>
